    'settings.routing.auto.enable': 'Auto-Modus aktivieren',
    'settings.routing.auto.enableInfo': 'Fügt „Auto“ zur Modellauswahl hinzu. Mit Auto wird jede gesendete Anfrage einer der Kategorien unten zugeordnet und läuft mit deren Modell, Denkstufe und Agent.',
