    'settings.routing.auto.preserveCacheInfo': 'Nach einem Modellwechsel liest das neue Modell die ganze Unterhaltung zum vollen Preis. Auto versucht zu erkennen, ob der Cache des aktuellen Modells abgelaufen ist, und wechselt bis dahin nicht in eine niedrigere Kategorie. In eine höhere wechselt Auto weiterhin sofort.',
