    'settings.routing.stickiness.enable': 'Beim aktuellen Modell bleiben',
    'settings.routing.stickiness.enableInfo': 'Auto behält das Modell einer Sitzung bei, sofern nicht mehrere Prompts in Folge auf ein anderes Modell hinweisen. So springen ähnliche Folgefragen nicht zwischen Modellen hin und her und der Prompt-Cache bleibt erhalten. Ein Prompt, den Auto nicht einordnen kann, behält das aktuelle Modell.',
